#!/usr/bin/env bash
# Round 291 claims (L29 + L56). Run from store/: bash ../tmp/studio-real-loop/b-round-290/claims-291.sh
L=../tmp/studio-real-loop
echo "K1 $(git rev-parse --short=7 HEAD) $(python3 -I -c "import json;g=json.load(open('$L/gates/gate-round-290.json'));print(g['status'])") $(python3 -I -c "import json;g=json.load(open('$L/gates/gate-round-289.json'));print(g['status'],g['commit'][:7])")"
echo "K2 $(git status --short --untracked-files=all | wc -l)"
echo "K3 $(wc -l < $L/b-round-290-r291-tree-sha256.txt) $(cmp -s $L/b-round-289-r290-tree-sha256.txt $L/b-round-290-r291-tree-sha256.txt && echo same-as-r290) $(sha256sum -c --quiet $L/b-round-290-r291-tree-sha256.txt >/dev/null 2>&1; echo rc$?)"
echo "K4 $(for f in 'app/routes/studio.$productId.tsx' app/routes/api.studio-token.ts app/routes/account.downloads.tsx app/lib/__tests__/download-routes.test.ts app/lib/auth.ts app/contexts/AuthContext.tsx app/entry.server.tsx; do grep -cF "  $f" $L/b-round-290-r291-tree-sha256.txt; done | tr '\n' ' ')"
echo "K5 $(grep -nE 'key=\{headingId\}|aria-labelledby=\{headingId\}|id=\{headingId\}' app/components/arrangement/ArrangementLibrary.tsx | sed -E 's/^([0-9]+):\s*/\1:/' | tr '\n' '|') aria-hidden=$(grep -c 'aria-hidden' app/components/arrangement/ArrangementLibrary.tsx)"
echo "K6 $(grep -n 'runs.push' app/components/arrangement/ArrangementLibrary.tsx | sed -E 's/^([0-9]+):\s*/\1:/')"
echo "K7 $(grep -nE "it\('ST(47|51):" app/lib/arrangement/__tests__/strings.test.ts | cut -d: -f1 | tr '\n' ' ')$(grep -cE 'keeps only the sound titles|except the demo sound titles' app/lib/arrangement/__tests__/strings.test.ts)"
echo "K8 $(grep -n 'ყოველთვის ჩანს' docs/implementation/2026/quarter-IV/216-fix-pd-demo-names-group-heading.md | cut -d: -f1) $(sed -n 4p docs/implementation/2026/quarter-IV/216-fix-pd-demo-names-group-heading.md)"
echo "K9 $(grep -nE '^\s*title=\{source\.title\}' app/components/arrangement/ArrangementLibrary.tsx | cut -d: -f1) $(grep -n 'title={source?.title}' app/components/arrangement/ArrangementLibraryPreview.tsx | cut -d: -f1)"
echo "K10 $(grep -oE 'collectionLabel: [A-Z_]+' app/data/studio-lab-demo.ts | sort -u | wc -l)"
echo "K11 $(ls docs/implementation/2026/quarter-IV/ | sort | tail -1 | cut -c1-3) $(ls docs/implementation/2026/quarter-IV/ | grep -c '^217')"
echo "K12 $(grep -cE 'onPointerDown(Capture)?|onBlur|settleEditor\(|\.focus\(|^\s*\{[^}]*(\.map\(|&&|\?)' app/components/arrangement/ArrangementLibrary.tsx) $(grep -n 'libraryResultRuns.length >= 2' app/components/arrangement/ArrangementLibrary.tsx | cut -d: -f1)"
echo "K13 $(for p in b-round-290/retro-290-before-291.md b-round-290/retro-diff.txt b-round-290/sketch-library.diff b-round-290/sketch-tests.diff b-round-290/sketch-key.diff b-round-290/sketch-lg8-test.diff b-round-290/sketch-results.txt b-round-290/scratch-covering.log b-round-290/mutant-M1-runindex-key.log b-round-290/mutant-M2-first-id-key.log b-round-290/mutant-M3-no-aria-hidden.log b-round-290/probe/ax-probe.mjs b-round-290/probe/ax-before.json b-round-290/probe/ax-sketch.json b-round-290/l50-hits.txt b-round-290/backlog-before-291.json b-round-290/probe/ax-before-1440x900.png b-round-290/probe/ax-before-1280x720.png b-round-290/probe/ax-sketch-1440x900.png b-round-290/probe/ax-sketch-1280x720.png b-round-290/claims-291-output.txt; do test -f $L/$p || echo MISSING $p; done; echo done)"
echo "K14 $(grep -c '2 test ფაილში 3 ტესტი' $L/retros/retro-290.md) $(grep -c '3 test ფაილი native' $L/retros/retro-290.md)"
echo "K15 $(sed 's/\x1b\[[0-9;]*m//g' $L/gates/round-276/verify.log | grep -E 'Test Files' | tr -s ' ')"
echo "K16 $(grep -oE "'LG[0-9]+" app/lib/arrangement/__tests__/library-group-heading-ui.test.tsx | sort -u | tr '\n' ' ')"
echo "K17 $(python3 -I -c "import json;d=json.load(open('$L/b-round-290/probe/ax-before.json'));print([(k,v['nonOptionChildrenInGroups'],v['textLinesInSnapshot'],v['bbox']['height']) for k,v in d.items()])")"
echo "K18 $(python3 -I -c "import json;d=json.load(open('$L/b-round-290/probe/ax-sketch.json'));print([(k,v['nonOptionChildrenInGroups'],v['textLinesInSnapshot'],v['bbox']['height']) for k,v in d.items()])")"
echo "K19 $(grep -c 'data-testid="arrangement-position"' app/components/arrangement/ArrangementTransport.tsx) $(grep -c 'data-playing=' app/components/arrangement/ArrangementTransport.tsx) $(grep -c "badge: 'Demo collection — no sign-in required'" app/lib/arrangement/collection.ts) $(grep -c "'Demo collection ready\." app/lib/arrangement/collection.ts) $(grep -c '>Sign in required<' app/components/auth/RequireAuth.tsx) $(grep -c "searchLabel: 'Search the library'" app/lib/arrangement/strings.ts) $(grep -c 'const SYNTHETIC_COLLECTION_LABEL = `Synthetic demo · ' app/data/studio-lab-demo.ts)"
